entries[428516] = { ["name"] = "Gelöscht", ["text"] = "Sofort\nFyrakk entzieht Glimmeron die geschmolzenen Energien und löscht ihn aus." }
entries[428517] = { ["name"] = "Gespaltene Seelen", ["text"] = "Die Seelen von Gegnern, die Schaden durch Euren Oberanführer erleiden, werden gespalten und erleiden 15 Sek. lang um 5 % erhöhten Schaden durch Euch und Eure Begleiter." }
entries[428518] = { ["name"] = "Geheimnisse des Zirkels", ["text"] = "Dämonologie\n'Mutter des Chaos' ermächtigt Euren nächsten Einsatz von 'Schattenblitz' zu 'Höllenblitz'.\n\nHöllenblitz\nSchleudert einen von höllischen Abgrundflammen umhüllten Blitz, der einem gegnerischen Ziel (538.94% der Zaubermacht) Feuerschaden zufügt und 3 Seelensplitter generiert.\n\nZerstörung\n'Mutter des Chaos' ermächtigt Euren nächsten Einsatz von 'Verbrennen' zu 'Höllenblitz'.\n\nHöllenblitz\nSchleudert einen von höllischen Abgrundflammen umhüllten Blitz, der einem gegnerischen Ziel (538.94% der Zaubermacht) Feuerschaden zufügt und 2 Seelensplitter generiert." }
