entries[429178] = { ["name"] = "Infloreszenz", ["text"] = "200 Meter Reichweite\nSofort\nWährend Ihr geht, erwacht der Boden unter Euren Füßen zu Leben, was Spielercharakteren erlaubt, sich unversehrt durch die ' Grüne Matrix ' zu bewegen, und ihre Bewegungsgeschwindigkeit um 50% erhöht. Hält 2 Sek. lang an." }
