entries[429184] = { ["name"] = "Windende Eruption", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Flammen umschlingen ihr Ziel komplett, wodurch sie 4 Sek. lang alle 1 Sek. 79776 Feuerschaden verursachen.\n\nBeim Ablauf explodiert das Ziel und verursacht 1087855 Feuerschaden, der unter allen Spielercharakteren innerhalb von 5 Metern um die Explosion aufgeteilt wird. Die Flammen schlängeln dann zu einem anderen Spielercharakter." }
