entries[429420] = { ["name"] = "Anhaltende Verzauberungen", ["text"] = "Gleichgewicht\n'Orbitalschlag' wendet 'Sterneneruption' 8 zusätzliche Sek. lang an und verursacht 30% mehr Schaden.\n\n'Wirbelnde Sterne' verringert die Abklingzeit von 'Himmlische Ausrichtung' um 10 weitere Sek.\n\nGleichgewicht (Inkarnation: Erwählter der Elune)\n'Orbitalschlag' wendet 'Sterneneruption' 8 zusätzliche Sek. lang an und verursacht 30% mehr Schaden.\n\n'Wirbelnde Sterne' verringert die Abklingzeit von 'Inkarnation: Erwählter der Elune'\n\nWiederherstellung\n'Wiederaufforstung' gewährt 'Baum des Lebens' für 3 weitere Sek." }
