entries[429536] = { ["name"] = "Astrale Einsicht", ["text"] = "Gleichgewicht\n'Inkarnation: Erwählter der Elune' erhöhen den Arkanschaden durch Zauber und Fähigkeiten um 10%, solange der Effekt aktiv ist.\n\nErhöht die Dauer und Anzahl der Zauber, die durch 'Konvokation der Geister' gewirkt werden, um 25%.\n\nWächter\n'Inkarnation: Wächter von Ursoc' erhöhen den Arkanschaden durch Zauber und Fähigkeiten um 10%, solange der Effekt aktiv ist.\n\nErhöht die Dauer und Anzahl der Zauber, die durch 'Konvokation der Geister' gewirkt werden, um 25%." }
