entries[429615] = { ["name"] = "Bedrohlicher Webrahmen", ["text"] = "Wirken in 2 sek.\nNymue beschwört einen magischen Webrahmen, der Fäden aus Energie in komplexe Muster webt.\n\nDiese Fäden bewegen sich dann langsam von Nymue fort, betäuben Spielercharakteren bei Berührung und verursachen 3 Sek. lang alle 1 Sek. 174057 Naturschaden." }
entries[429616] = { ["name"] = "Wahnsinn verursachen", ["text"] = "30 Meter Reichweite\nSofort\nTreibt ein gegnerisches Ziel für begrenzte Zeit in den Wahnsinn und erhöht so sein Angriffstempo um 100%, während es seine Bewegungsgeschwindigkeit um 50% verringert. Zudem greift es 10 Sek. lang seine eigenen Verbündeten an." }
entries[429617] = { ["name"] = "Flammen schüren", ["text"] = "100 Meter Reichweite\nSofort\nDurch ' Flamme der Hoffnung ' beeinträchtigte Ziele explodieren, was Gegnern innerhalb von 12 Metern Gegnern (25% der Zaubermacht + 25% der Angriffskraft) Feuerschaden zufügt und Verbündete um (37.5% der Zaubermacht + 37.5% der Angriffskraft) Gesundheit heilt." }
