entries[429634] = { ["name"] = "Kolossale Macht", ["text"] = "Schutz\nEure 'Kolossale Macht' erhöht den verursachten Schaden Eures nächsten Einsatzes von 'Demolieren' um 10%. Bis zu 5-mal stapelbar.\n\n'Schildschlag' gewährt einen Stapel von 'Kolossale Macht' und 'Rache' gewährt einen Stapel von 'Kolossale Macht', wenn die Fähigkeit 3 oder mehr Ziele trifft.\n\nWaffen\nEure 'Kolossale Macht' erhöht den verursachten Schaden Eures nächsten Einsatzes von 'Demolieren' um 10%. Bis zu 5-mal stapelbar.\n\n'Tödlicher Stoß' gewährt einen Stapel von 'Kolossale Macht' und 'Spalten' gewährt einen Stapel von 'Kolossale Macht', wenn die Fähigkeit 3 oder mehr Ziele trifft." }
entries[429635] = { ["name"] = "Kolossaler Sturmangriff", ["text"] = "Eure 'Kolossale Macht' schüchtert Eure Gegner ein. Erhöht Eure kritische Trefferchance und kritische Blockchance bei Gegnern, die von Eurem 'Kolosseinschlag' betroffen sind, 6 Sek. lang um 1% pro Stapel." }
entries[429636] = { ["name"] = "Dominanz des Kolosses", ["text"] = "Waffen\n'Kolossale Macht' ist bis zu 10-mal stapelbar. Wenn Ihr bei maximalen Stapeln sonst einen Stapel 'Kolossale Macht' erhalten würdet, verringert sich die Abklingzeit von 'Demolieren' um 2 Sek.\n\nVon 'Demolieren' betroffene Gegner erleiden bis zu 10% mehr Schaden durch Euch und fügen Euch bis zu 10% weniger Schaden zu, abhängig davon, wie viele Stapel 'Kolossale Macht' von 'Demolieren' verbraucht wurden. Hält 10 Sek. lang an.\n\nSchutz\n'Kolossale Macht' ist bis zu 10-mal stapelbar. Wenn Ihr bei maximalen Stapeln sonst einen Stapel 'Kolossale Macht' erhalten würdet, verringert sich die Abklingzeit von 'Demolieren' um 4 Sek.\n\nVon 'Demolieren' betroffene Gegner erleiden bis zu 20% mehr Schaden durch Euch und fügen Euch bis zu 10% weniger Schaden zu, abhängig davon, wie viele Stapel 'Kolossale Macht' von 'Demolieren' verbraucht wurden. Hält 10 Sek. lang an." }
entries[429637] = { ["name"] = "Einer gegen Viele", ["text"] = "Schutz\n'Schockwelle', 'Rache' und 'Wirbelwind' verursachen pro betroffenem Ziel (bis zu 5 Ziele) 3% mehr Schaden.\n\nWaffen\n'Schockwelle', 'Spalten' und 'Wirbelwind' verursachen pro betroffenem Ziel (bis zu 5 Ziele) 5% mehr Schaden." }
entries[429638] = { ["name"] = "Kampfkunstexperte", ["text"] = "Erhöht den kritischen Schaden Eurer Fähigkeiten um 10% sowie die Schadensmenge, die Ihr mit kritischem Blocken blockt, um 20%." }
entries[429639] = { ["name"] = "Knochenerschütterer", ["text"] = "Erhöht die Betäubungsdauer von 'Schockwelle' um 1 Sek. und verringert die Bewegungsgeschwindigkeit betroffener Gegner für 3 Sek., nachdem die Betäubung endet, um 40%." }
entries[429641] = { ["name"] = "Kriegsglück", ["text"] = "Schutz\nEure 'Kolossale Macht' erhöht den Schaden von 'Rache' um 7% pro Stapel.\n\nWaffen\nEure 'Kolossale Macht' erhöht den Schaden von 'Überwältigen' um 5% pro Stapel." }
entries[429642] = { ["name"] = "Narbiger Muskelberg", ["text"] = "Ihr verursacht 5% mehr Schaden und erleidet 5.0% weniger Schaden.\n\nErhöht die Größe um 5%." }
entries[429643] = { ["name"] = "Volldampf", ["text"] = "Waffen:\n'Schockwelle' und 'Wirbelwind' erhöhen den Durchschlagsschaden Eures nächsten Einsatzes von 'Kolosseinschlag' um 10%. Bis zu 3-mal stapelbar.\n\nSchutz:\n'Schockwelle' und 'Rache' erhöhen den Durchschlagsschaden Eures nächsten Einsatzes von 'Kolosseinschlag' um 10%. Bis zu 3-mal stapelbar." }
