entries[429645] = { ["name"] = "Gewalt führt zu Gewalt", ["text"] = "Waffen: 'Überwältigen' hat eine Chance von 1% pro Stapel von 'Kolossale Macht', die Abklingzeit von 'Tödlicher Stoß' abzuschließen.\n\nSchutz: 'Verwüster' hat eine um 1% erhöhte Chance pro Stapel von 'Kolossale Macht', die Abklingzeit von 'Schildschlag' abzuschließen." }
