entries[429945] = { ["name"] = "Erwecktes Wappen des verzauberten Wyrms", ["text"] = "Wirken in 3 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nChromatischer Staub (60), Pulsierender Splitter (10), Resonierender Kristall (2), Dracothyst , Erwecktes Wappen des heranwachsenden Wyrms\nQuest:\nEin letztes Hurra: Dracheninseln\nQuest:\nEin letztes Hurra: Zaralekhöhle und Zeitrisse\nQuest:\nEin letztes Hurra: Smaragdgrüner Traum\n\nErwecktes Wappen des verzauberten Wyrms\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+30 Rezeptschwierigkeit\nBenutzbar mit: Rezepte der Dracheninseln für epische Ausrüstungsteile, die mit einem Funken der Erweckung hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"" }
entries[429946] = { ["name"] = "Schattenkäfig", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer dunkle Koloss hüllt mehrere Spielercharaktere in Schatten, die nach 4 Sek. ausbrechen und allen Spielercharakteren innerhalb von 5 Metern 362618 Schattenschaden zufügen.\n\nSpielercharaktere im Bereich des Ausbruchs werden betäubt und erleiden alle 2 Sek. 36262 Schattenschaden." }
entries[429947] = { ["name"] = "Erwecktes Wappen des verzauberten Aspekts", ["text"] = "Wirken in 3 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nChromatischer Staub (80), Pulsierender Splitter (15), Resonierender Kristall (4), Dracothyst (2), Erwecktes Wappen des heranwachsenden Aspekts\nQuest:\nEin letztes Hurra: Dracheninseln\nQuest:\nEin letztes Hurra: Zaralekhöhle und Zeitrisse\nQuest:\nEin letztes Hurra: Smaragdgrüner Traum\n\nErwecktes Wappen des verzauberten Aspekts\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+50 Rezeptschwierigkeit\nBenutzbar mit: Rezepte der Dracheninseln für epische Ausrüstungsteile, die mit einem Funken der Erweckung hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"" }
entries[429948] = { ["name"] = "Erwecktes Wappen des verzauberten Welpen", ["text"] = "Wirken in 3 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nChromatischer Staub (30), Pulsierender Splitter (5), Resonierender Kristall , Erwecktes Wappen des heranwachsenden Welpen\nQuest:\nEin letztes Hurra: Dracheninseln\nQuest:\nEin letztes Hurra: Zaralekhöhle und Zeitrisse\nQuest:\nEin letztes Hurra: Smaragdgrüner Traum\n\nErwecktes Wappen des verzauberten Welpen\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+160 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"" }
